photo = "畠山直哉が撮り続けた岩手県陸前高田の気仙川は、故郷の川という一つの被写体に、数十年にわたる異なる時間を重ねて撮影されている。二千十一年の震災前後を通じて同じ川筋、同じ橋、同じ堤を捉えたフレームは、風景が失われた記録であると同時に、失われたのちも同じ場所へ再びカメラを向け続けた撮影者のまなざしそのものの記録でもある。印画された一枚一枚は単独の完成形ではなく、束ねられた写真集というかたちで初めて、同一の場所に降り積もった複数の時間を並べて見せる。ページをめくるごとに切り替わる同じ構図の反復が、更新という行為を視覚的な律動に変えている。"

book = "亀山郁夫による『悪霊』新訳は全三巻で本編を終えているが、光文社古典新訳文庫はその後に別巻を重ね、「スタヴローギンの告白」の異稿を収めた。この章はもともと雑誌連載時に編集者との間で扱いが割れ、本体とは別の系統で伝わってきた経緯を持つ一章である。別巻という形式そのものが、完結したはずの三巻本を開き直す装置になっている。異稿を読む体験は、既に読み終えた本編の構成を頭の中で組み替える作業に近く、一冊の書物が刊行後もなお版を重ねて姿を変えうることを、注釈でなく本文の追加という形で示している。"

rest = "日比谷公園の敷地内に建つ洋食レストランは、明治期の開園当初から公園に付属する食事処として営業してきた。昭和四十六年に火災で建物を失いながら、屋号と場所を変えずに二年後の再開を選んだ。焼失以前の内装や什器の多くは失われたが、公園という敷地の位置づけと店の名だけは途切れさせずに引き継がれている。再開を支えた常連客への感謝として始まった一日限りの割引提供は、以後も毎年続けられ、店の来歴を客の側から更新し続ける行事になっている。皿の上に並ぶハヤシライスやカレーは戦前からの定番だが、それを出す建物と経営の連続性のほうが、この店にとっての主題である。"

for name, t in [("photo", photo), ("book", book), ("rest", rest)]:
    print(name, len(t))
